"use strict";
// BE-E: replayable counterfactual bouts from actual browser career checkpoints.
// Inputs are generated by: npm run test:browser -- --grep 'BE-E carrière longue'
const fs = require("node:fs");
const assert = require("node:assert/strict");
const combat = require("../combat-engine.js");
const roster = require("../roster-engine.js");
const adapter = require("../roster-career.js");
const samples = Math.max(100, Number(process.env.BE_E_SAMPLES) || 300);
const mean = vector => Object.values(vector).reduce((a, b) => a + b, 0) / 4;
const round = n => Math.round(n * 100) / 100;
function policies(name) {
  return {
    coach: (state, options) => options.find(c => c.id === "recover" && state.fighters.player.energy < 35)
      || options.find(c => c.recommended) || options[0],
    action: (state, options) => name === "novice" ? options[(state.round + state.exchange) % options.length]
      : options.find(c => c.directiveAligned) || options[0],
  };
}
function measure(player, opponent, name, key) {
  let wins = 0, stops = 0;
  for (let i = 0; i < samples; i += 1) {
    const result = combat.simulateFight({ seed: `BE-E:${key}:${i}`, kind: "local", exchangesPerRound: 5,
      actionChoiceCount: 5, opponentDifficulty: opponent.difficulty, coachQuality: .60,
      player, opponent: { ...opponent, id: "opponent" } }, policies(name)).result;
    assert.ok(["player", "opponent"].includes(result.winner));
    wins += result.winner === "player" ? 1 : 0;
    stops += result.method !== "decision" ? 1 : 0;
  }
  const p = wins / samples, z = 1.96, d = 1 + z * z / samples;
  const center = (p + z * z / (2 * samples)) / d;
  const margin = z * Math.sqrt(p * (1 - p) / samples + z * z / (4 * samples * samples)) / d;
  return { samples, wins, winPercent: round(100 * p), interval95: [round(100 * (center - margin)), round(100 * (center + margin))], stops };
}
const profiles = ["debutant", "regulier", "avance-migre"];
const campaigns = profiles.map(name => {
  const desktop = JSON.parse(fs.readFileSync(`/tmp/boxeur-be-e-${name}-1366.json`, "utf8"));
  const mobile = JSON.parse(fs.readFileSync(`/tmp/boxeur-be-e-${name}-390.json`, "utf8"));
  assert.equal(desktop.config.weeks, 104, "Run the full 104-week campaign, not the smoke test");
  // No viewport-dependent formulas or RNG differences permitted.
  assert.deepEqual(desktop, mobile);
  const observations = desktop.observations.map(point => ({ ...point,
    bouts: point.offers.map((opponent, slot) => ({ name: opponent.name, rating: round(opponent.rating),
      risk: opponent.risk, gap: round(opponent.rating - point.strength),
      actualCondition: measure(point.combatPlayer, opponent, desktop.config.policy, `${name}:${point.week}:${slot}`),
      freshCondition: measure({ ...point.combatPlayer, energy: 90, fatigue: 5 }, opponent, desktop.config.policy, `${name}:${point.week}:${slot}`),
    })),
  }));
  return { name, policy: desktop.config.policy, observations,
    played: desktop.fights.length, won: desktop.fights.filter(f => f.winner === "player").length,
    distinctOpponents: [...new Set(desktop.fights.map(f => f.opponent))],
    maximumFatigue: Math.max(...desktop.weeks.map(w => w.fatigue)), minimumEnergy: Math.min(...desktop.weeks.map(w => w.energy)),
    finalMoney: desktop.weeks.at(-1).money, playerFinalAverage: desktop.weeks.at(-1).playerAverage,
    rosterBytesUTF8: desktop.rosterBytesUTF8, saveBytesUTF8: desktop.saveBytesUTF8,
    automaticFights: desktop.finalRoster.matches.filter(m => m.source === "simulation").length,
  };
});
// Fresh comparable baselines isolate the policy from the selected careers.
const vector = n => ({ technique: n, power: n, cardio: n, defense: n });
const baselines = ["novice", "coached"].map(policy => ({ policy,
  ...measure({ stats: vector(45), energy: 90, fatigue: 5, fitness: 50, injury: 0, morale: 50 },
    { stats: vector(45), difficulty: 45, style: "Équilibré" }, policy, "comparable") }));
// Both sexes, late capped roster, deliberately over-levelled player, and 99 migration.
const edges = [];
for (const sex of ["male", "female"]) {
  for (const offset of [0, 56]) {
    let state = roster.createState({ sex, weightClass: sex === "male" ? "M65" : "W57", seed: "BE-E-edge", initialLevelOffset: offset });
    for (let week = 1; week <= 520; week += 1) state = roster.advanceWeek(state, { week, careerStatus: "amateur", completed: true }).state;
    const offers = adapter.galaOffers(state, { id: "edge", opponentSlots: [{ ratingOffset: -4 }, { ratingOffset: 0 }, { ratingOffset: 3 }] }, 95);
    assert.equal(new Set(offers.map(o => o.rosterFighterId)).size, 3);
    assert.ok(state.fighters.every(f => Object.keys(f.stats).every(key => f.stats[key] <= f.ceilings[key] && f.stats[key] <= 99)));
    edges.push({ sex, offset, low: round(Math.min(...state.fighters.map(f => mean(f.stats)))), high: round(Math.max(...state.fighters.map(f => mean(f.stats)))),
      offers: offers.map(o => ({ name: o.name, risk: o.risk, rating: round(o.rating) })) });
  }
}
const output = { samples, note: "Scripted tactics, no animation or voluntary ring movement. Not human win probabilities. Fresh condition is a counterfactual, not a save edit.",
  desktopMobileIdentical: true, campaigns, baselines, edges };
fs.writeFileSync("/tmp/boxeur-be-e-balance.json", JSON.stringify(output, null, 2));
console.log(JSON.stringify({ samples, desktopMobileIdentical: true, baselines, edges, campaigns: campaigns.map(c => ({ ...c,
  observations: c.observations.map(p => ({ week: p.week, average: p.average, energy: p.energy, fatigue: p.fatigue,
    min: p.rosterMinimum, max: p.rosterMaximum, bouts: p.bouts })) })) }, null, 2));
